  1→<!DOCTYPE html>
  2→<html lang="en">
  3→<head>
  4→  <meta charset="UTF-8" />
  5→  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  6→  <title>Menu Scanner</title>
  7→  <style>
  8→    /* ── Reset & base ─────────────────────────────────────────────── */
  9→    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
 10→
 11→    :root {
 12→      --ink:        #1a1a18;
 13→      --ink-2:      #4a4a44;
 14→      --ink-3:      #8a8a82;
 15→      --paper:      #faf9f6;
 16→      --paper-2:    #f2f0eb;
 17→      --paper-3:    #e8e5de;
 18→      --rule:       #dedad2;
 19→      --accent:     #c84b31;     /* editorial red */
 20→      --accent-dk:  #a33a22;
 21→      --amber:      #b45309;
 22→      --amber-bg:   #fef3c7;
 23→      --amber-bd:   #fbbf24;
 24→      --green:      #166534;
 25→      --green-bg:   #dcfce7;
 26→      --green-bd:   #86efac;
 27→      --blue:       #1e40af;
 28→      --blue-bg:    #dbeafe;
 29→      --blue-bd:    #93c5fd;
 30→      --radius:     6px;
 31→      --shadow:     0 1px 3px rgba(0,0,0,.07), 0 4px 16px rgba(0,0,0,.06);
 32→    }
 33→
 34→    html { font-size: 16px; }
 35→
 36→    body {
 37→      font-family: 'Georgia', 'Times New Roman', serif;
 38→      background: var(--paper);
 39→      color: var(--ink);
 40→      min-height: 100vh;
 41→      padding: 3rem 1rem 5rem;
 42→    }
 43→
 44→    /* ── Layout ───────────────────────────────────────────────────── */
 45→    .page {
 46→      max-width: 760px;
 47→      margin: 0 auto;
 48→    }
 49→
 50→    /* ── Masthead ─────────────────────────────────────────────────── */
 51→    .masthead {
 52→      text-align: center;
 53→      border-top: 3px solid var(--ink);
 54→      border-bottom: 1px solid var(--ink);
 55→      padding: 1.25rem 0 1rem;
 56→      margin-bottom: 2.5rem;
 57→    }
 58→    .masthead-kicker {
 59→      font-family: 'Helvetica Neue', Arial, sans-serif;
 60→      font-size: .68rem;
 61→      font-weight: 700;
 62→      letter-spacing: .14em;
 63→      text-transform: uppercase;
 64→      color: var(--accent);
 65→      margin-bottom: .4rem;
 66→    }
 67→    .masthead h1 {
 68→      font-size: clamp(2rem, 6vw, 3.2rem);
 69→      font-weight: 400;
 70→      letter-spacing: -.02em;
 71→      line-height: 1;
 72→    }
 73→    .masthead-sub {
 74→      font-family: 'Helvetica Neue', Arial, sans-serif;
 75→      font-size: .82rem;
 76→      color: var(--ink-2);
 77→      margin-top: .5rem;
 78→    }
 79→
 80→    /* ── Upload zone ──────────────────────────────────────────────── */
 81→    .upload-section { margin-bottom: 1.5rem; }
 82→
 83→    .drop-zone {
 84→      position: relative;
 85→      border: 1.5px dashed var(--paper-3);
 86→      border-radius: var(--radius);
 87→      background: var(--paper-2);
 88→      padding: 2.5rem 1.5rem;
 89→      text-align: center;
 90→      cursor: pointer;
 91→      transition: border-color .18s, background .18s;
 92→      user-select: none;
 93→    }
 94→    .drop-zone:hover,
 95→    .drop-zone.drag-over {
 96→      border-color: var(--accent);
 97→      background: #fdf6f4;
 98→    }
 99→    .drop-zone input[type=file] {
100→      position: absolute; inset: 0; opacity: 0; cursor: pointer; width: 100%; height: 100%;
101→    }
102→    .drop-icon {
103→      width: 40px; height: 40px;
104→      margin: 0 auto .75rem;
105→      color: var(--ink-3);
106→    }
107→    .drop-title {
108→      font-family: 'Helvetica Neue', Arial, sans-serif;
109→      font-size: .9rem;
110→      font-weight: 600;
111→      color: var(--ink-2);
112→    }
113→    .drop-hint {
114→      font-family: 'Helvetica Neue', Arial, sans-serif;
115→      font-size: .75rem;
116→      color: var(--ink-3);
117→      margin-top: .3rem;
118→    }
119→
120→    /* ── Preview ──────────────────────────────────────────────────── */
121→    .preview-wrap {
122→      position: relative;
123→      display: none;
124→      margin-bottom: 1.25rem;
125→      border-radius: var(--radius);
126→      overflow: hidden;
127→      background: var(--paper-3);
128→      max-height: 320px;
129→    }
130→    .preview-wrap img {
131→      display: block;
132→      width: 100%;
133→      max-height: 320px;
134→      object-fit: contain;
135→    }
136→    .preview-clear {
137→      position: absolute;
138→      top: .5rem; right: .5rem;
139→      width: 26px; height: 26px;
140→      background: rgba(26,26,24,.7);
141→      color: #fff;
142→      border: none;
143→      border-radius: 50%;
144→      font-size: .85rem;
145→      line-height: 26px;
146→      text-align: center;
147→      cursor: pointer;
148→      display: flex; align-items: center; justify-content: center;
149→    }
150→    .preview-clear:hover { background: var(--accent); }
151→
152→    /* ── Scan button ──────────────────────────────────────────────── */
153→    .scan-btn {
154→      display: none;
155→      width: 100%;
156→      padding: .85rem 1rem;
157→      background: var(--ink);
158→      color: var(--paper);
159→      border: none;
160→      border-radius: var(--radius);
161→      font-family: 'Helvetica Neue', Arial, sans-serif;
162→      font-size: .88rem;
163→      font-weight: 700;
164→      letter-spacing: .08em;
165→      text-transform: uppercase;
166→      cursor: pointer;
167→      transition: background .18s;
168→    }
169→    .scan-btn:hover:not(:disabled) { background: var(--accent); }
170→    .scan-btn:disabled { opacity: .45; cursor: not-allowed; }
171→
172→    /* ── Loader ───────────────────────────────────────────────────── */
173→    .loader {
174→      display: none;
175→      align-items: center;
176→      gap: .75rem;
177→      font-family: 'Helvetica Neue', Arial, sans-serif;
178→      font-size: .82rem;
179→      color: var(--ink-2);
180→      margin-top: 1rem;
181→    }
182→    .loader.visible { display: flex; }
183→    .spinner {
184→      width: 18px; height: 18px;
185→      border: 2px solid var(--rule);
186→      border-top-color: var(--ink);
187→      border-radius: 50%;
188→      animation: spin .7s linear infinite;
189→      flex-shrink: 0;
190→    }
191→    @keyframes spin { to { transform: rotate(360deg); } }
192→
193→    /* ── Error banner ─────────────────────────────────────────────── */
194→    .error-banner {
195→      display: none;
196→      background: #fef2f2;
197→      border: 1px solid #fca5a5;
198→      color: #991b1b;
199→      border-radius: var(--radius);
200→      padding: .75rem 1rem;
201→      font-family: 'Helvetica Neue', Arial, sans-serif;
202→      font-size: .84rem;
203→      margin-top: 1rem;
204→    }
205→    .error-banner.visible { display: block; }
206→
207→    /* ── Results section ──────────────────────────────────────────── */
208→    .results-header {
209→      display: none;
210→      align-items: baseline;
211→      justify-content: space-between;
212→      border-bottom: 1px solid var(--ink);
213→      padding-bottom: .4rem;
214→      margin-bottom: 1.25rem;
215→    }
216→    .results-header.visible { display: flex; }
217→    .results-title {
218→      font-family: 'Helvetica Neue', Arial, sans-serif;
219→      font-size: .7rem;
220→      font-weight: 700;
221→      letter-spacing: .12em;
222→      text-transform: uppercase;
223→      color: var(--ink-2);
224→    }
225→    .results-count {
226→      font-family: 'Helvetica Neue', Arial, sans-serif;
227→      font-size: .7rem;
228→      color: var(--ink-3);
229→    }
230→
231→    /* ── Item card ────────────────────────────────────────────────── */
232→    .item-card {
233→      padding: 1.1rem 0;
234→      border-bottom: 1px solid var(--rule);
235→    }
236→    .item-card:last-child { border-bottom: none; }
237→
238→    .item-top {
239→      display: flex;
240→      align-items: baseline;
241→      justify-content: space-between;
242→      gap: 1rem;
243→      flex-wrap: wrap;
244→      margin-bottom: .3rem;
245→    }
246→    .item-name {
247→      font-size: 1.05rem;
248→      font-weight: 400;
249→      letter-spacing: -.01em;
250→    }
251→
252→    .item-badges {
253→      display: flex;
254→      flex-wrap: wrap;
255→      gap: .3rem;
256→      margin-bottom: .45rem;
257→    }
258→
259→    .badge {
260→      font-family: 'Helvetica Neue', Arial, sans-serif;
261→      font-size: .68rem;
262→      font-weight: 700;
263→      letter-spacing: .06em;
264→      text-transform: uppercase;
265→      padding: .15rem .5rem;
266→      border-radius: 999px;
267→      border: 1px solid transparent;
268→    }
269→    .badge-amber  { background: var(--amber-bg);  color: var(--amber); border-color: var(--amber-bd); }
270→    .badge-green  { background: var(--green-bg);  color: var(--green); border-color: var(--green-bd); }
271→    .badge-blue   { background: var(--blue-bg);   color: var(--blue);  border-color: var(--blue-bd); }
272→
273→    .item-desc {
274→      font-size: .9rem;
275→      color: var(--ink-2);
276→      line-height: 1.55;
277→      margin-bottom: .55rem;
278→    }
279→
280→    /* ── Ingredients row ──────────────────────────────────────────── */
281→    .item-meta {
282→      font-family: 'Helvetica Neue', Arial, sans-serif;
283→      font-size: .78rem;
284→      color: var(--ink-3);
285→      line-height: 1.5;
286→    }
287→    .item-meta strong {
288→      color: var(--ink-2);
289→      font-weight: 600;
290→    }
291→
292→    /* ── Obscure notes (expandable) ───────────────────────────────── */
293→    .obscure-toggle {
294→      display: inline-flex;
295→      align-items: center;
296→      gap: .25rem;
297→      background: none;
298→      border: none;
299→      font-family: 'Helvetica Neue', Arial, sans-serif;
300→      font-size: .75rem;
301→      font-weight: 600;
302→      color: var(--accent);
303→      cursor: pointer;
304→      padding: 0;
305→      margin-top: .4rem;
306→      text-decoration: underline;
307→      text-decoration-style: dotted;
308→      text-underline-offset: 2px;
309→    }
310→    .obscure-toggle .arr { transition: transform .18s; display: inline-block; }
311→    .obscure-toggle[aria-expanded="true"] .arr { transform: rotate(90deg); }
312→
313→    .obscure-list {
314→      display: none;
315→      margin-top: .45rem;
316→      padding: .6rem .75rem;
317→      background: var(--paper-2);
318→      border-left: 2px solid var(--accent);
319→      border-radius: 0 var(--radius) var(--radius) 0;
320→    }
321→    .obscure-list.open { display: block; }
322→    .obscure-list li {
323→      font-family: 'Helvetica Neue', Arial, sans-serif;
324→      font-size: .78rem;
325→      color: var(--ink-2);
326→      list-style: none;
327→      padding: .2rem 0;
328→      line-height: 1.45;
329→    }
330→    .obscure-list li + li { border-top: 1px solid var(--rule); }
331→
332→    /* ── Card entrance animation ─────────────────────────────────── */
333→    @keyframes cardIn {
334→      from { opacity: 0; transform: translateY(10px); }
335→      to   { opacity: 1; transform: translateY(0); }
336→    }
337→    .item-card {
338→      animation: cardIn .32s cubic-bezier(.22,.68,0,1.1) both;
339→    }
340→    @media (prefers-reduced-motion: reduce) {
341→      .item-card { animation: none; }
342→    }
343→
344→    /* ── Empty state ──────────────────────────────────────────────── */
345→    .empty-state {
346→      text-align: center;
347→      padding: 2.5rem 1rem;
348→      font-family: 'Helvetica Neue', Arial, sans-serif;
349→      font-size: .85rem;
350→      color: var(--ink-3);
351→    }
352→  </style>
353→</head>
354→<body>
355→<div class="page">
356→
357→  <!-- Masthead -->
358→  <header class="masthead">
359→    <p class="masthead-kicker">AI-Powered</p>
360→    <h1>Menu Scanner</h1>
361→    <p class="masthead-sub">Upload a menu photograph &mdash; get ingredients, allergens &amp; dietary notes instantly</p>
362→  </header>
363→
364→  <!-- Upload -->
365→  <section class="upload-section">
366→    <div class="drop-zone" id="dropZone" role="button" tabindex="0" aria-label="Upload menu image">
367→      <input type="file" id="fileInput" accept="image/jpeg,image/png,image/webp,image/gif" aria-hidden="true" />
368→      <svg class="drop-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
369→        <rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8.5" cy="8.5" r="1.5"/>
370→        <polyline points="21 15 16 10 5 21"/>
371→      </svg>
372→      <p class="drop-title">Drop a menu image here, or click to browse</p>
373→      <p class="drop-hint">JPEG &middot; PNG &middot; WEBP &middot; GIF</p>
374→    </div>
375→
376→    <div class="preview-wrap" id="previewWrap">
377→      <img id="preview" alt="Menu preview" />
378→      <button class="preview-clear" id="clearBtn" aria-label="Remove image">&times;</button>
379→    </div>
380→
381→    <button class="scan-btn" id="scanBtn">Scan Menu</button>
382→
383→    <div class="loader" id="loader" aria-live="polite">
384→      <div class="spinner"></div>
385→      <span id="loaderText">Analysing menu&hellip;</span>
386→    </div>
387→
388→    <div class="error-banner" id="errorBanner" role="alert"></div>
389→  </section>
390→
391→  <!-- Results -->
392→  <section id="resultsSection">
393→    <div class="results-header" id="resultsHeader">
394→      <span class="results-title">Menu Items</span>
395→      <span class="results-count" id="resultsCount"></span>
396→    </div>
397→    <div id="results"></div>
398→  </section>
399→
400→</div>
401→
402→<script>
403→  const API_BASE = 'http://localhost:8000';
404→
405→  const dropZone    = document.getElementById('dropZone');
406→  const fileInput   = document.getElementById('fileInput');
407→  const previewWrap = document.getElementById('previewWrap');
408→  const preview     = document.getElementById('preview');
409→  const clearBtn    = document.getElementById('clearBtn');
410→  const scanBtn     = document.getElementById('scanBtn');
411→  const loader      = document.getElementById('loader');
412→  const loaderText  = document.getElementById('loaderText');
413→  const errorBanner = document.getElementById('errorBanner');
414→  const resultsHeader = document.getElementById('resultsHeader');
415→  const resultsCount  = document.getElementById('resultsCount');
416→  const results     = document.getElementById('results');
417→
418→  let selectedFile = null;
419→
420→  // ── File handling ────────────────────────────────────────────────
421→
422→  function handleFile(file) {
423→    if (!file) return;
424→    const allowed = ['image/jpeg', 'image/png', 'image/webp', 'image/gif'];
425→    if (!allowed.includes(file.type)) {
426→      showError(`Unsupported file type "${file.type}". Please upload a JPEG, PNG, WEBP, or GIF.`);
427→      return;
428→    }
429→    selectedFile = file;
430→    const url = URL.createObjectURL(file);
431→    preview.src = url;
432→    previewWrap.style.display = 'block';
433→    scanBtn.style.display = 'block';
434→    hideError();
435→    clearResults();
436→  }
437→
438→  function resetUpload() {
439→    selectedFile = null;
440→    fileInput.value = '';
441→    preview.src = '';
442→    previewWrap.style.display = 'none';
443→    scanBtn.style.display = 'none';
444→    hideError();
445→    clearResults();
446→  }
447→
448→  fileInput.addEventListener('change', () => handleFile(fileInput.files[0]));
449→  clearBtn.addEventListener('click', (e) => { e.stopPropagation(); resetUpload(); });
450→
451→  // Keyboard activation for drop zone
452→  dropZone.addEventListener('keydown', (e) => {
453→    if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); fileInput.click(); }
454→  });
455→
456→  dropZone.addEventListener('dragover', (e) => { e.preventDefault(); dropZone.classList.add('drag-over'); });
457→  dropZone.addEventListener('dragleave', (e) => {
458→    if (!dropZone.contains(e.relatedTarget)) dropZone.classList.remove('drag-over');
459→  });
460→  dropZone.addEventListener('drop', (e) => {
461→    e.preventDefault();
462→    dropZone.classList.remove('drag-over');
463→    handleFile(e.dataTransfer.files[0]);
464→  });
465→
466→  // ── Scan ─────────────────────────────────────────────────────────
467→
468→  scanBtn.addEventListener('click', async () => {
469→    if (!selectedFile) return;
470→
471→    setLoading(true);
472→    hideError();
473→    clearResults();
474→
475→    const messages = [
476→      'Analysing menu\u2026',
477→      'Identifying ingredients\u2026',
478→      'Checking allergens\u2026',
479→      'Almost there\u2026',
480→    ];
481→    let msgIdx = 0;
482→    const msgInterval = setInterval(() => {
483→      msgIdx = (msgIdx + 1) % messages.length;
484→      loaderText.textContent = messages[msgIdx];
485→    }, 2200);
486→
487→    try {
488→      const formData = new FormData();
489→      formData.append('file', selectedFile);
490→
491→      const res = await fetch(`${API_BASE}/scan`, { method: 'POST', body: formData });
492→
493→      if (!res.ok) {
494→        let detail = `Server error ${res.status}`;
495→        try { const body = await res.json(); detail = body.detail || detail; } catch {}
496→        throw new Error(detail);
497→      }
498→
499→      const data = await res.json();
500→      const items = data.items;
501→
502→      if (!Array.isArray(items) || items.length === 0) {
503→        clearInterval(msgInterval);
504→        setLoading(false);
505→        results.innerHTML = '<div class="empty-state">No menu items could be identified in this image.</div>';
506→        resultsHeader.classList.add('visible');
507→        resultsCount.textContent = '0 items';
508→        return;
509→      }
510→
511→      clearInterval(msgInterval);
512→      setLoading(false);
513→      renderItems(items);
514→
515→    } catch (err) {
516→      clearInterval(msgInterval);
517→      setLoading(false);
518→      showError(err.message);
519→    }
520→  });
521→
522→  // ── Render ───────────────────────────────────────────────────────
523→
524→  function renderItems(items) {
525→    resultsHeader.classList.add('visible');
526→    resultsCount.textContent = `${items.length} item${items.length !== 1 ? 's' : ''}`;
527→
528→    results.innerHTML = items.map((item, idx) => {
529→      const name        = esc(item.name ?? 'Unnamed item');
530→      const desc        = item.description ? `<p class="item-desc">${esc(item.description)}</p>` : '';
531→      const allergens   = (item.allergy_warnings   || []).filter(Boolean);
532→      const dietary     = (item.dietary_flags       || []).filter(Boolean);
533→      const common      = (item.common_ingredients  || []).filter(Boolean);
534→      const obscure     = (item.obscure_ingredient_notes || []).filter(Boolean);
535→
536→      // Badges: allergens (amber), dietary (green/blue alternating)
537→      const allergenBadges = allergens.map(a =>
538→        `<span class="badge badge-amber">${esc(a)}</span>`
539→      ).join('');
540→      const dietaryBadges = dietary.map(d =>
541→        `<span class="badge badge-green">${esc(d)}</span>`
542→      ).join('');
543→      const badges = (allergenBadges || dietaryBadges)
544→        ? `<div class="item-badges">${allergenBadges}${dietaryBadges}</div>`
545→        : '';
546→
547→      // Ingredients row
548→      const commonStr = common.length
549→        ? `<p class="item-meta"><strong>Ingredients:</strong> ${esc(common.join(', '))}</p>`
550→        : '';
551→
552→      // Obscure notes — expandable
553→      let obscureHtml = '';
554→      if (obscure.length) {
555→        const listItems = obscure.map(n => `<li>${esc(n)}</li>`).join('');
556→        const id = `obscure-${idx}`;
557→        obscureHtml = `
558→          <button class="obscure-toggle" aria-expanded="false" aria-controls="${id}">
559→            <span class="arr">&#9658;</span> ${obscure.length} obscure ingredient note${obscure.length !== 1 ? 's' : ''}
560→          </button>
561→          <ul class="obscure-list" id="${id}">${listItems}</ul>`;
562→      }
563→
564→      return `
565→        <article class="item-card" style="animation-delay:${idx * 60}ms">
566→          <div class="item-top">
567→            <h2 class="item-name">${name}</h2>
568→          </div>
569→          ${badges}
570→          ${desc}
571→          ${commonStr}
572→          ${obscureHtml}
573→        </article>`;
574→    }).join('');
575→
576→    // Wire up expandable toggles
577→    results.querySelectorAll('.obscure-toggle').forEach(btn => {
578→      btn.addEventListener('click', () => {
579→        const expanded = btn.getAttribute('aria-expanded') === 'true';
580→        btn.setAttribute('aria-expanded', String(!expanded));
581→        const list = document.getElementById(btn.getAttribute('aria-controls'));
582→        list.classList.toggle('open', !expanded);
583→      });
584→    });
585→  }
586→
587→  // ── UI helpers ───────────────────────────────────────────────────
588→
589→  function setLoading(on) {
590→    scanBtn.disabled = on;
591→    loader.classList.toggle('visible', on);
592→    if (!on) loaderText.textContent = 'Analysing menu\u2026';
593→  }
594→
595→  function showError(msg) {
596→    errorBanner.textContent = msg;
597→    errorBanner.classList.add('visible');
598→  }
599→  function hideError() {
600→    errorBanner.classList.remove('visible');
601→    errorBanner.textContent = '';
602→  }
603→
604→  function clearResults() {
605→    results.innerHTML = '';
606→    resultsHeader.classList.remove('visible');
607→    resultsCount.textContent = '';
608→  }
609→
610→  function esc(str) {
611→    return String(str)
612→      .replace(/&/g, '&amp;')
613→      .replace(/</g, '&lt;')
614→      .replace(/>/g, '&gt;')
615→      .replace(/"/g, '&quot;');
616→  }
617→</script>
618→</body>
619→</html>
