429→<body>
430→<div class="page">
431→
432→  <!-- Masthead -->
433→  <header class="masthead">
434→    <p class="masthead-kicker">AI-Powered</p>
435→    <h1>Menu Scanner</h1>
436→    <p class="masthead-sub">Upload a menu photograph &mdash; get ingredients, allergens &amp; dietary notes instantly</p>
437→  </header>
438→
439→  <!-- Upload -->
440→  <section class="upload-section">
441→    <div class="drop-zone" id="dropZone" role="button" tabindex="0" aria-label="Upload menu image">
442→      <input type="file" id="fileInput" accept="image/jpeg,image/png,image/webp,image/gif" aria-hidden="true" />
443→      <svg class="drop-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
444→        <rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8.5" cy="8.5" r="1.5"/>
445→        <polyline points="21 15 16 10 5 21"/>
446→      </svg>
447→      <p class="drop-title">Drop a menu image here, or click to browse</p>
448→      <p class="drop-hint">JPEG &middot; PNG &middot; WEBP &middot; GIF</p>
449→    </div>
450→
451→    <div class="preview-wrap" id="previewWrap">
452→      <img id="preview" alt="Menu preview" />
453→      <button class="preview-clear" id="clearBtn" aria-label="Remove image">&times;</button>
454→    </div>
455→
456→    <div class="dietary-section" id="dietarySection">
457→      <label class="dietary-label" for="dietaryInput">Your dietary restrictions (comma-separated)</label>
458→      <input class="dietary-input" type="text" id="dietaryInput" placeholder="e.g. gluten, shellfish, vegan, dairy" />
459→      <div class="dietary-tags" id="dietaryTags"></div>
460→      <button class="dietary-clear-all" id="dietaryClearAll" type="button">Clear all</button>
461→    </div>
462→
463→    <button class="scan-btn" id="scanBtn">Scan Menu</button>
464→
465→    <div class="loader" id="loader" aria-live="polite">
466→      <div class="spinner"></div>
467→      <span id="loaderText">Analysing menu&hellip;</span>
468→    </div>
469→
470→    <div class="error-banner" id="errorBanner" role="alert"></div>
471→  </section>
472→
473→  <!-- Results -->
474→  <section id="resultsSection">
475→    <div class="results-header" id="resultsHeader">
476→      <span class="results-title">Menu Items</span>
477→      <span class="results-count" id="resultsCount"></span>
478→    </div>
479→    <div id="results"></div>
480→  </section>
481→
482→</div>
483→
484→<script>
485→  const API_BASE = 'http://localhost:8000';
486→
487→  const dropZone    = document.getElementById('dropZone');
488→  const fileInput   = document.getElementById('fileInput');
489→  const previewWrap = document.getElementById('previewWrap');
490→  const preview     = document.getElementById('preview');
491→  const clearBtn    = document.getElementById('clearBtn');
492→  const scanBtn     = document.getElementById('scanBtn');
493→  const loader      = document.getElementById('loader');
494→  const loaderText  = document.getElementById('loaderText');
495→  const errorBanner = document.getElementById('errorBanner');
496→  const resultsHeader = document.getElementById('resultsHeader');
497→  const resultsCount  = document.getElementById('resultsCount');
498→  const results     = document.getElementById('results');
499→
500→  const dietarySection  = document.getElementById('dietarySection');
501→  const dietaryInput    = document.getElementById('dietaryInput');
502→  const dietaryTags     = document.getElementById('dietaryTags');
503→  const dietaryClearAll = document.getElementById('dietaryClearAll');
504→
505→  let selectedFile = null;
506→  let restrictions = [];
507→
508→  // ── File handling ────────────────────────────────────────────────
509→
510→  function handleFile(file) {
511→    if (!file) return;
512→    const allowed = ['image/jpeg', 'image/png', 'image/webp', 'image/gif'];
513→    if (!allowed.includes(file.type)) {
514→      showError(`Unsupported file type "${file.type}". Please upload a JPEG, PNG, WEBP, or GIF.`);
515→      return;
516→    }
517→    selectedFile = file;
518→    const url = URL.createObjectURL(file);
519→    preview.src = url;
520→    previewWrap.style.display = 'block';
521→    scanBtn.style.display = 'block';
522→    dietarySection.classList.add('visible');
523→    hideError();
524→    clearResults();
525→  }
526→
527→  function resetUpload() {
528→    selectedFile = null;
529→    fileInput.value = '';
530→    preview.src = '';
531→    previewWrap.style.display = 'none';
532→    scanBtn.style.display = 'none';
533→    hideError();
534→    clearResults();
535→  }
536→
537→  fileInput.addEventListener('change', () => handleFile(fileInput.files[0]));
538→  clearBtn.addEventListener('click', (e) => { e.stopPropagation(); resetUpload(); });
539→
540→  // Keyboard activation for drop zone
541→  dropZone.addEventListener('keydown', (e) => {
542→    if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); fileInput.click(); }
543→  });
544→
545→  dropZone.addEventListener('dragover', (e) => { e.preventDefault(); dropZone.classList.add('drag-over'); });
546→  dropZone.addEventListener('dragleave', (e) => {
547→    if (!dropZone.contains(e.relatedTarget)) dropZone.classList.remove('drag-over');
548→  });
549→  dropZone.addEventListener('drop', (e) => {
550→    e.preventDefault();
551→    dropZone.classList.remove('drag-over');
552→    handleFile(e.dataTransfer.files[0]);
553→  });
554→
555→  // ── Scan ─────────────────────────────────────────────────────────
556→
557→  scanBtn.addEventListener('click', async () => {
558→    if (!selectedFile) return;
559→
560→    setLoading(true);
561→    hideError();
562→    clearResults();
563→
564→    const messages = [
565→      'Analysing menu\u2026',
566→      'Identifying ingredients\u2026',
567→      'Checking allergens\u2026',
568→      'Almost there\u2026',
569→    ];
570→    let msgIdx = 0;
571→    const msgInterval = setInterval(() => {
572→      msgIdx = (msgIdx + 1) % messages.length;
573→      loaderText.textContent = messages[msgIdx];
574→    }, 2200);
575→
576→    try {
577→      const formData = new FormData();
578→      formData.append('file', selectedFile);
579→
580→      const res = await fetch(`${API_BASE}/scan`, { method: 'POST', body: formData });
581→
582→      if (!res.ok) {
583→        let detail = `Server error ${res.status}`;
584→        try { const body = await res.json(); detail = body.detail || detail; } catch {}
585→        throw new Error(detail);
586→      }
587→
588→      const data = await res.json();
589→      const items = data.items;
590→
591→      if (!Array.isArray(items) || items.length === 0) {
592→        clearInterval(msgInterval);
593→        setLoading(false);
594→        results.innerHTML = '<div class="empty-state">No menu items could be identified in this image.</div>';
595→        resultsHeader.classList.add('visible');
596→        resultsCount.textContent = '0 items';
597→        return;
598→      }
599→
600→      clearInterval(msgInterval);
601→      setLoading(false);
602→      renderItems(items);
603→
604→    } catch (err) {
605→      clearInterval(msgInterval);
606→      setLoading(false);
607→      showError(err.message);
608→    }
609→  });
610→
611→  // ── Render ───────────────────────────────────────────────────────
612→
613→  function renderItems(items) {
614→    resultsHeader.classList.add('visible');
615→    resultsCount.textContent = `${items.length} item${items.length !== 1 ? 's' : ''}`;
616→
617→    results.innerHTML = items.map((item, idx) => {
618→      const name        = esc(item.name ?? 'Unnamed item');
619→      const desc        = item.description ? `<p class="item-desc">${esc(item.description)}</p>` : '';
620→      const allergens   = (item.allergy_warnings   || []).filter(Boolean);
621→      const dietary     = (item.dietary_flags       || []).filter(Boolean);
622→      const common      = (item.common_ingredients  || []).filter(Boolean);
623→      const obscure     = (item.obscure_ingredient_notes || []).filter(Boolean);
624→
625→      // Badges: allergens (amber), dietary (green/blue alternating)
626→      const allergenBadges = allergens.map(a =>
627→        `<span class="badge badge-amber">${esc(a)}</span>`
628→      ).join('');
629→      const dietaryBadges = dietary.map(d =>
630→        `<span class="badge badge-green">${esc(d)}</span>`
631→      ).join('');
632→      const badges = (allergenBadges || dietaryBadges)
633→        ? `<div class="item-badges">${allergenBadges}${dietaryBadges}</div>`
634→        : '';
635→
636→      // Ingredients row
637→      const commonStr = common.length
638→        ? `<p class="item-meta"><strong>Ingredients:</strong> ${esc(common.join(', '))}</p>`
639→        : '';
640→
641→      // Obscure notes — expandable
642→      let obscureHtml = '';
643→      if (obscure.length) {
644→        const listItems = obscure.map(n => `<li>${esc(n)}</li>`).join('');
645→        const id = `obscure-${idx}`;
646→        obscureHtml = `
647→          <button class="obscure-toggle" aria-expanded="false" aria-controls="${id}">
648→            <span class="arr">&#9658;</span> ${obscure.length} obscure ingredient note${obscure.length !== 1 ? 's' : ''}
649→          </button>
650→          <ul class="obscure-list" id="${id}">${listItems}</ul>`;
651→      }
652→
653→      return `
654→        <article class="item-card" style="animation-delay:${idx * 60}ms">
655→          <div class="item-top">
656→            <h2 class="item-name">${name}</h2>
657→          </div>
658→          ${badges}
659→          ${desc}
660→          ${commonStr}
661→          ${obscureHtml}
662→        </article>`;
663→    }).join('');
664→
665→    // Wire up expandable toggles
666→    results.querySelectorAll('.obscure-toggle').forEach(btn => {
667→      btn.addEventListener('click', () => {
668→        const expanded = btn.getAttribute('aria-expanded') === 'true';
669→        btn.setAttribute('aria-expanded', String(!expanded));
670→        const list = document.getElementById(btn.getAttribute('aria-controls'));
671→        list.classList.toggle('open', !expanded);
672→      });
673→    });
674→  }
675→
676→  // ── UI helpers ───────────────────────────────────────────────────
677→
678→  function setLoading(on) {
679→    scanBtn.disabled = on;
680→    loader.classList.toggle('visible', on);
681→    if (!on) loaderText.textContent = 'Analysing menu\u2026';
682→  }
683→
684→  function showError(msg) {
685→    errorBanner.textContent = msg;
686→    errorBanner.classList.add('visible');
687→  }
688→  function hideError() {
689→    errorBanner.classList.remove('visible');
690→    errorBanner.textContent = '';
691→  }
692→
693→  function clearResults() {
694→    results.innerHTML = '';
695→    resultsHeader.classList.remove('visible');
696→    resultsCount.textContent = '';
697→  }
698→
699→  function esc(str) {
700→    return String(str)
701→      .replace(/&/g, '&amp;')
702→      .replace(/</g, '&lt;')
703→      .replace(/>/g, '&gt;')
704→      .replace(/"/g, '&quot;');
705→  }
706→</script>
707→</body>
708→</html>
