// ── Dietary tag input ────────────────────────────────────────────

function addTag(text) {
  const tag = text.trim().toLowerCase();
  if (!tag || restrictions.includes(tag)) return;
  restrictions.push(tag);
  renderTags();
}

function removeTag(tag) {
  restrictions = restrictions.filter(t => t !== tag);
  renderTags();
}

