import json
import logging
from pathlib import Path

import openai
from fastapi import FastAPI, File, HTTPException, UploadFile
from fastapi.middleware.cors import CORSMiddleware
from fastapi.responses import FileResponse
from fastapi.staticfiles import StaticFiles

from extractor import extract_menu

FRONTEND_DIR = Path(__file__).resolve().parent.parent / "frontend"

logger = logging.getLogger(__name__)

ALLOWED_MIME_TYPES = {"image/jpeg", "image/png", "image/webp", "image/gif"}

app = FastAPI()

app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_methods=["*"],
    allow_headers=["*"],
)


@app.post("/scan")
async def scan_menu(file: UploadFile = File(...)):
    mime = file.content_type or ""
    if mime not in ALLOWED_MIME_TYPES:
        raise HTTPException(
            status_code=415,
            detail=f"Unsupported file type '{mime}'. Upload a JPEG, PNG, WEBP, or GIF image.",
        )

    image_bytes = await file.read()

    try:
        items = extract_menu(image_bytes, mime_type=mime)
    except openai.OpenAIError as exc:
        logger.exception("OpenAI API error")
        raise HTTPException(status_code=502, detail=f"OpenAI error: {exc}") from exc
    except json.JSONDecodeError as exc:
        logger.exception("Model returned malformed JSON")
        raise HTTPException(
            status_code=502,
            detail=f"Model returned malformed JSON: {exc}",
        ) from exc
    except Exception as exc:
        logger.exception("Unexpected error during extraction")
        raise HTTPException(status_code=500, detail=str(exc)) from exc

    return {"items": items}


@app.get("/health")
def health():
    return {"status": "ok"}


@app.get("/")
def root():
    return FileResponse(FRONTEND_DIR / "index.html")


app.mount("/", StaticFiles(directory=FRONTEND_DIR), name="frontend")

