async def scan_menu(file: UploadFile = File(...)):
    mime = file.content_type or ""
    if mime not in ALLOWED_MIME_TYPES:
        raise HTTPException(
            status_code=415,
            detail=f"Unsupported file type '{mime}'. Upload a JPEG, PNG, WEBP, or GIF image.",
        )

    image_bytes = await file.read()

    try:
